    EnvCheck -->|"macOS"| Mac["Use Codex.app CLI Path"]
    EnvCheck -->|"Linux"| Linux["Check CODEX_BIN or npm codex"]
    EnvCheck -->|"Windows"| Win["Use Codex.exe CLI Path"]
    Mac --> Exec["Execute generate.py with prompt, size, output_dir"]
    Linux --> Exec
    Win --> Exec
    Exec --> CLI["Codex CLI executes DALL-E 3 Prompt"]
    CLI --> QuotaCheck{"Account Quota Available?"}
